let plates = [];
let plateY = 200;
let plateWidth = 12;
let plateHeight = 280;
let plateGap = 140;
let plateX1, plateX2;
let particles = [];
let showField = true;
let forceArrow = 0;
let time = 0;
let dragging = -1;

function setup() {
  createCanvas(800, 500);
  plateX1 = width/2 - plateGap/2 - plateWidth/2;
  plateX2 = width/2 + plateGap/2 - plateWidth/2;
  plates.push({ x: plateX1, w: plateWidth });
  plates.push({ x: plateX2, w: plateWidth });

  for (let i = 0; i < 300; i++) {
    particles.push(new Particle());
  }
}

function draw() {
  background(15, 20, 35);
  time += 0.02;

  // Draw labels
  fill(200);
  noStroke();
  textSize(16);
  textAlign(CENTER, TOP);
  text("CASIMIR EFFECT SIMULATION", width/2, 15);
  textSize(13);
  fill(180);
  text("Drag the plates together or apart. Notice fewer vacuum fluctuations between plates.", width/2, 45);
  text("Higher vacuum energy outside pushes plates inward.", width/2, 65);

  // Draw background zones
  fill(30, 35, 55, 100);
  noStroke();
  rect(0, plateY - plateHeight/2 - 30, plateX1, plateHeight + 60);
  rect(plateX1 + plateWidth, plateY - plateHeight/2 - 30, plateX2 - plateX1 - plateWidth, plateHeight + 60);
  rect(plateX2 + plateWidth, plateY - plateHeight/2 - 30, width - plateX2 - plateWidth, plateHeight + 60);

  // Draw wave mode lines between plates (quantized modes)
  stroke(100, 150, 255, 60);
  strokeWeight(1);
  let betweenWidth = plateX2 - (plateX1 + plateWidth);
  let maxModes = 4;
  let modesAllowed = max(1, floor(200 / betweenWidth * 4));
  for (let m = 1; m <= modesAllowed && m <= maxModes; m++) {
    let wavelength = 2 * betweenWidth / m;
    for (let x = plateX1 + plateWidth; x <= plateX2; x += wavelength) {
      line(x, plateY - plateHeight/2, x + wavelength/2, plateY + plateHeight/2);
    }
  }

  // Labels for regions
  noStroke();
  fill(120, 180, 255, 150);
  textSize(11);
  textAlign(CENTER, BOTTOM);
  text("Unconfined vacuum (many modes)", (plateX1)/2, plateY - plateHeight/2 - 35);
  textAlign(CENTER, BOTTOM);
  text("Unconfined vacuum (many modes)", plateX2 + (width - plateX2 - plateWidth)/2 + plateWidth/2, plateY - plateHeight/2 - 35);
  fill(255, 200, 120, 150);
  textAlign(CENTER, BOTTOM);
  text("CONFINED vacuum (restricted modes)", plateX1 + betweenWidth/2 + plateWidth/2, plateY - plateHeight/2 - 35);

  // Update and draw particles
  for (let p of particles) {
    p.update();
    p.display();
  }

  // Draw force arrows
  let gap = plateX2 - (plateX1 + plateWidth);
  let pressure = 8000 / (gap * gap + 200);
  let arrowSize = min(pressure, 60);

  stroke(255, 80, 80, 200);
  strokeWeight(3);
  fill(255, 80, 80, 200);
  // Left plate pushed right
  let ax1 = plateX1 + plateWidth/2;
  line(ax1 - arrowSize, plateY, ax1, plateY);
  triangle(ax1, plateY, ax1 - 8, plateY - 4, ax1 - 8, plateY + 4);
  // Right plate pushed left
  let ax2 = plateX2 + plateWidth/2;
  line(ax2 + arrowSize, plateY, ax2, plateY);
  triangle(ax2, plateY, ax2 + 8, plateY - 4, ax2 + 8, plateY + 4);

  // Draw plates
  for (let i = 0; i < plates.length; i++) {
    let px = i === 0 ? plateX1 : plateX2;
    // Plate body - metallic gradient
    for (let gx = 0; gx < plateWidth; gx++) {
      let inter = map(gx, 0, plateWidth, 0, 1);
      let c = lerpColor(color(180, 185, 190), color(100, 105, 110), inter);
      stroke(c);
      line(px + gx, plateY - plateHeight/2, px + gx, plateY + plateHeight/2);
    }
    // Plate border
    stroke(220, 225, 230);
    strokeWeight(2);
    noFill();
    rect(px, plateY - plateHeight/2, plateWidth, plateHeight, 3);

    // Plate label
    fill(255);
    noStroke();
    textSize(12);
    textAlign(CENTER, CENTER);
    text(i === 0 ? "Plate 1" : "Plate 2", px + plateWidth/2, plateY);

    // Handle for dragging
    fill(255, 255, 255, 30);
    if (dist(mouseX, mouseY, px + plateWidth/2, plateY) < 30) {
      fill(255, 255, 255, 80);
      cursor(HAND);
    }
    noStroke();
    rect(px - 5, plateY - 15, plateWidth + 10, 30, 5);
  }

  if (dist(mouseX, mouseY, plateX1 + plateWidth/2, plateY) > 30 && 
      dist(mouseX, mouseY, plateX2 + plateWidth/2, plateY) > 30) {
    cursor(ARROW);
  }

  // Gap measurement
  let midGap = plateX1 + plateWidth + betweenWidth/2;
  stroke(255, 200, 80, 180);
  strokeWeight(1);
  line(plateX1 + plateWidth, plateY + plateHeight/2 + 25, plateX2, plateY + plateHeight/2 + 25);
  line(plateX1 + plateWidth, plateY + plateHeight/2 + 20, plateX1 + plateWidth, plateY + plateHeight/2 + 30);
  line(plateX2, plateY + plateHeight/2 + 20, plateX2, plateY + plateHeight/2 + 30);
  noStroke();
  fill(255, 200, 80);
  textSize(12);
  textAlign(CENTER, TOP);
  text("gap: " + floor(betweenWidth) + " px", midGap, plateY + plateHeight/2 + 32);

  // Force text
  fill(255, 120, 120);
  textAlign(CENTER, BOTTOM);
  textSize(13);
  text("Casimir Attraction ↑", width/2, plateY + plateHeight/2 + 25);
}

function mousePressed() {
  if (dist(mouseX, mouseY, plateX1 + plateWidth/2, plateY) < 35) {
    dragging = 0;
  } else if (dist(mouseX, mouseY, plateX2 + plateWidth/2, plateY) < 35) {
    dragging = 1;
  }
}

function mouseDragged() {
  if (dragging === 0) {
    plateX1 = constrain(mouseX - plateWidth/2, 50, plateX2 - plateWidth - 30);
  } else if (dragging === 1) {
    plateX2 = constrain(mouseX - plateWidth/2, plateX1 + plateWidth + 30, width - 50 - plateWidth);
  }
}

function mouseReleased() {
  dragging = -1;
}

class Particle {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width);
    this.y = random(plateY - plateHeight/2, plateY + plateHeight/2);
    this.baseSize = random(2, 5);
    this.size = 0;
    this.life = random(30, 90);
    this.maxLife = this.life;
    this.active = true;
    this.vx = random(-0.5, 0.5);
    this.vy = random(-0.5, 0.5);
    this.type = random() > 0.5 ? 'matter' : 'antimatter';
    this.betweenPlates = false;
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.life--;

    // Check if between plates
    this.betweenPlates = (this.x > plateX1 + plateWidth && this.x < plateX2);
    let betweenWidth = plateX2 - (plateX1 + plateWidth);

    // In Casimir effect: between plates, only certain modes fit
    // So if between plates and wavelength too large, suppress
    let minWavelength = betweenWidth / 2; // Simplified mode restriction
    let particleEffectiveWavelength = this.baseSize * 15;

    if (this.betweenPlates && particleEffectiveWavelength > betweenWidth && betweenWidth < 180) {
      // Suppressed between plates (doesn't "fit")
      this.life -= 3; // Die faster
    }

    // Fade in and out
    if (this.life > this.maxLife - 10) {
      this.size = map(this.life, this.maxLife - 10, this.maxLife, 0, this.baseSize);
    } else if (this.life < 10) {
      this.size = map(this.life, 0, 10, 0, this.baseSize);
    } else {
      this.size = this.baseSize;
    }

    if (this.life <= 0 || this.x < 0 || this.x > width || this.y < plateY - plateHeight/2 || this.y > plateY + plateHeight/2) {
      this.reset();
    }
  }

  display() {
    let alpha = map(this.life, 0, this.maxLife, 0, 200);
    noStroke();
    if (this.type === 'matter') {
      fill(80, 180, 255, alpha);
    } else {
      fill(255, 100, 120, alpha);
    }
    ellipse(this.x, this.y, this.size * 2, this.size * 2);

    // Glow
    if (this.size > 2) {
      fill(200, 220, 255, alpha * 0.2);
      ellipse(this.x, this.y, this.size * 5, this.size * 5);
    }
  }
}

